import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.DXa1R37q.js";const h=JSON.parse('{"title":"Claude Code","description":"","frontmatter":{},"headers":[],"relativePath":"harnesses/claude-code.md","filePath":"harnesses/claude-code.md","lastUpdated":1793122404000}'),s={name:"harnesses/claude-code.md"};function n(i,e,r,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h1><p>Neottia compiles and installs the canonical SDLC for Claude Code through <a href="https://www.npmjs.com/package/@neottia/claude-code-adapter" target="_blank" rel="noreferrer"><code>@neottia/claude-code-adapter</code></a>. The adapter declares documented Claude Code behavior and returns reviewable plans. The distribution installer writes approved assets and configuration. The adapter itself never writes files or runs the Claude Code binary.</p><h2 id="tested-support" tabindex="-1">Tested support <a class="header-anchor" href="#tested-support" aria-label="Permalink to &quot;Tested support&quot;">​</a></h2><p>The adapter projects these assets. Paths follow the <a href="https://code.claude.com/docs/en/overview" target="_blank" rel="noreferrer">Claude Code documentation</a>.</p><table tabindex="0"><thead><tr><th>Asset</th><th>Project</th><th>Global</th></tr></thead><tbody><tr><td>Command</td><td><code>.claude/commands/&lt;id&gt;.md</code></td><td><code>~/.claude/commands/&lt;id&gt;.md</code></td></tr><tr><td>Skill</td><td><code>.claude/skills/&lt;id&gt;/SKILL.md</code></td><td><code>~/.claude/skills/&lt;id&gt;/SKILL.md</code></td></tr><tr><td>Agent</td><td><code>.claude/agents/&lt;id&gt;.md</code></td><td><code>~/.claude/agents/&lt;id&gt;.md</code></td></tr><tr><td>MCP configuration</td><td><code>.mcp.json</code></td><td>Unsupported</td></tr></tbody></table><p>Command frontmatter supports <code>description</code>, <code>argument-hint</code>, <code>model</code>, and documented subagent routing. A portable subtask request maps to <code>context: fork</code>, and an explicit agent selection emits both <code>context: fork</code> and the documented <code>agent</code> field. Agent files support <code>name</code>, <code>description</code>, <code>model</code>, <code>effort</code>, and <code>maxTurns</code>. The portable per-tool permission map has no documented agent-file representation, so permission metadata returns a diagnostic instead of being dropped.</p><p>MCP plans target the committed project file <code>.mcp.json</code> under <code>mcpServers</code>. Local servers use the documented <code>type: &quot;stdio&quot;</code> shape with <code>command</code> and optional <code>args</code> and <code>env</code>; remote servers use <code>type: &quot;http&quot;</code> with <code>url</code> and optional <code>headers</code>. Per-server <code>timeout</code> values follow the documented minimum of 1000 milliseconds. The adapter does not edit user-managed state such as <code>~/.claude.json</code>, so MCP configuration is project-scoped only. Claude Code also requires interactive approval of project <code>.mcp.json</code> servers after installation.</p><p>The default Issues and Design Docs modules use exact <code>@neottia/issues-mcp</code> and <code>@neottia/design-docs-mcp</code> versions. Optional Memory and Searchable modules use their exact generic MCP packages when enabled. Each entry launches through <code>npx --yes --package &lt;name&gt;@&lt;version&gt; &lt;executable&gt;</code>. The package version comes from the CLI compatibility catalog, not from a registry lookup during planning.</p><h2 id="unsupported-and-deferred-support" tabindex="-1">Unsupported and deferred support <a class="header-anchor" href="#unsupported-and-deferred-support" aria-label="Permalink to &quot;Unsupported and deferred support&quot;">​</a></h2><ul><li>Claude Code plugin distribution. Neottia uses generic MCP servers for runtime tools because single-file extension requests cannot represent the multi-file plugin format.</li><li>User-scope MCP configuration. The installer does not edit <code>~/.claude.json</code>. Global commands, skills, and agents remain available, but a lifecycle with runtime modules must use project scope.</li><li>Codex, Kiro, GitHub Copilot CLI, and Visual Studio Code Copilot. Issue <a href="https://github.com/dragoscirjan/neottia/issues/119" target="_blank" rel="noreferrer">#119</a> keeps these harnesses deferred.</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Install Node.js 22.20 or newer, pnpm 10 or newer, and ensure <code>npx</code> is on <code>PATH</code>. Run the following commands from the target repository root, or pass <code>--project DIR</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @neottia/cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>After installation, restart Claude Code so commands, agents, and MCP configuration load together. Open <code>/mcp</code> and approve each project server from <code>.mcp.json</code>. This approval is a Claude Code security boundary. Neottia does not bypass it. The restart recommendation is Neottia adapter policy; Claude Code reloads some resources live but does not document one reload command for every asset type.</p><h2 id="authentication-and-configuration" tabindex="-1">Authentication and configuration <a class="header-anchor" href="#authentication-and-configuration" aria-label="Permalink to &quot;Authentication and configuration&quot;">​</a></h2><p>Claude Code manages its own sign-in, settings files, and OAuth for remote MCP servers. Neottia plans keep Claude Code environment references such as <code>\${ISSUES_TOKEN}</code> unresolved and never write authentication state. Configure host authentication separately from Neottia installation.</p><p>Repository validation proves deterministic adapter projection, compiler output, installation receipts, <code>.mcp.json</code> preservation, doctor output, and packed external-consumer installation. It does not execute a Claude Code binary in CI, so the adapter does not list a tested host version.</p>`,17)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
